var BLUE = '#14506e', TEAL = '#2a9d8f', ORANGE = '#e07b39', GRAY = '#444';
function f(x){ return 3*x + 1 + 2/(x-1); }
var probeX = -4, viewMode = 'both';

var canvas = document.createElement('canvas');
canvas.style.width = '100%'; canvas.style.height = '100%'; canvas.style.display = 'block';
document.getElementById('container').appendChild(canvas);

function u(s){ return Math.max(9, Math.round(s*0.030)); } // font unit

var figPlugin = {
  id: 'fig',
  afterDraw: function(chart){
    var ca = chart.chartArea, ctx = chart.ctx;
    var xs = chart.scales.x, ys = chart.scales.y;
    var px = function(v){ return xs.getPixelForValue(v); };
    var py = function(v){ return ys.getPixelForValue(v); };
    var s = Math.min(ca.width, ca.height), fs = u(s);
    ctx.clearRect(ca.left-40, ca.top-40, ca.width+80, ca.height+80);

    // ---- clipped region: asymptotes + curve ----
    ctx.save();
    ctx.beginPath(); ctx.rect(ca.left, ca.top, ca.width, ca.height); ctx.clip();

    var showAsym = (viewMode !== 'curve'), showCurve = (viewMode !== 'asym');

    if (showAsym){
      // slant asymptote y = 3x+1
      ctx.strokeStyle = TEAL; ctx.lineWidth = Math.max(1.5, s*0.006);
      ctx.setLineDash([6,5]);
      ctx.beginPath();
      ctx.moveTo(px(-5), py(-14)); ctx.lineTo(px(4.5), py(14.5));
      ctx.stroke();
      // vertical asymptote x = 1
      ctx.strokeStyle = ORANGE;
      ctx.beginPath();
      ctx.moveTo(px(1), py(-14)); ctx.lineTo(px(1), py(14.5));
      ctx.stroke();
      ctx.setLineDash([]);
    }

    if (showCurve){
      ctx.strokeStyle = BLUE; ctx.lineWidth = Math.max(2, s*0.008);
      ctx.lineJoin = 'round'; ctx.lineCap = 'round';
      [[-4.8, 0.86],[1.14, 4.3]].forEach(function(dom){
        ctx.beginPath();
        var started = false;
        for (var i=0;i<=300;i++){
          var x = dom[0] + (dom[1]-dom[0])*i/300, y = f(x);
          if (y < -14.5 || y > 14.5){ started = false; continue; }
          if (!started){ ctx.moveTo(px(x), py(y)); started = true; }
          else ctx.lineTo(px(x), py(y));
        }
        ctx.stroke();
      });
      // arrowheads at branch ends
      ctx.fillStyle = BLUE;
      var ah = Math.max(5, s*0.022);
      function arrow(x0,y0,x1,y1){
        var a = Math.atan2(py(y1)-py(y0), px(x1)-px(x0));
