        ctx.beginPath();
        ctx.moveTo(X, Y);
        ctx.lineTo(X - ah*Math.cos(a-0.42), Y - ah*Math.sin(a-0.42));
        ctx.lineTo(X - ah*Math.cos(a+0.42), Y - ah*Math.sin(a+0.42));
        ctx.closePath(); ctx.fill();
      }
      arrow(-4.4, f(-4.4), -4.55, f(-4.55));
      arrow(3.9, f(3.9), 4.05, f(4.05));
      arrow(0.95, f(0.95), 0.9, f(0.9));
      arrow(1.1, f(1.1), 1.06, f(1.06));
    }

    // ---- probe + guides ----
    var fx = f(probeX);
    if (showCurve && Math.abs(probeX-1) > 0.06 && fx > -14 && fx < 14){
      var PX = px(probeX), PY = py(fx);
      ctx.lineWidth = Math.max(1.2, s*0.005);
      if (showAsym){
        // orange guide to x = 1
        ctx.strokeStyle = ORANGE;
        ctx.beginPath(); ctx.moveTo(PX, PY); ctx.lineTo(px(1), PY); ctx.stroke();
        ctx.fillStyle = ORANGE; ctx.font = fs + 'px sans-serif';
        ctx.textAlign = 'center';
        var dV = Math.abs(probeX-1);
        var ly = PY + (fx > 0 ? fs*1.4 : -fs*0.6);
        ctx.fillText('d = ' + dV.toFixed(2), (PX+px(1))/2, ly);
        // teal perpendicular guide to slant line 3x - y + 1 = 0
        var dS = Math.abs(3*probeX - fx + 1)/Math.sqrt(10);
        var fx2 = (3*fx + 9*probeX - 3)/10, fy2 = 3*fx2 + 1; // foot of perpendicular
        ctx.strokeStyle = TEAL;
        ctx.beginPath(); ctx.moveTo(PX, PY); ctx.lineTo(px(fx2), py(fy2)); ctx.stroke();
        ctx.fillStyle = TEAL; ctx.textAlign = 'left';
        ctx.fillText('d = ' + dS.toFixed(2), (PX+px(fx2))/2 + 4, (PY+py(fy2))/2);
      }
      // probe dot + label
      ctx.fillStyle = BLUE;
      ctx.beginPath(); ctx.arc(PX, PY, Math.max(3.5, s*0.014), 0, 7); ctx.fill();
      ctx.font = 'bold ' + fs + 'px sans-serif';
      ctx.textAlign = probeX > 2.4 ? 'right' : 'left';
      var lx = PX + (probeX > 2.4 ? -8 : 8), lyy = PY - 8;
      ctx.fillStyle = '#000';
      ctx.strokeStyle = '#fff'; ctx.lineWidth = 3; ctx.lineJoin = 'round';
      var txt = '(' + probeX.toFixed(2) + ', ' + fx.toFixed(2) + ')';
