    axisArrow(px(0), ca.bottom, px(0), ca.top);
    // ticks
    ctx.font = fs*0.85 + 'px sans-serif';
    ctx.textAlign = 'center';
    for (var xt=-5; xt<=5; xt++){
      if (xt === 0) continue;
      var X = px(xt);
      ctx.beginPath(); ctx.moveTo(X, py(0)-3); ctx.lineTo(X, py(0)+3); ctx.stroke();
      ctx.fillText(xt, X, py(0)+fs*1.1);
    }
    ctx.fillText('0', px(0)-fs*0.6, py(0)+fs*1.1);
