      ctx.beginPath(); ctx.moveTo(px(0)-3, Y); ctx.lineTo(px(0)+3, Y); ctx.stroke();
      ctx.fillText(yt, px(0)-5, Y+fs*0.3);
    }
    ctx.font = 'bold italic ' + fs + 'px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('x', ca.right - fs, py(0)-fs*0.5);
    ctx.fillText('y', px(0)+fs*0.5, ca.top + fs*0.9);

    // ---- asymptote labels ----
    ctx.lineJoin = 'round';
    function haloText(t, x, y, color, align){
      ctx.font = 'bold ' + fs + 'px sans-serif';
      ctx.textAlign = align || 'left';
      ctx.strokeStyle = '#fff'; ctx.lineWidth = 4;
      ctx.strokeText(t, x, y);
      ctx.fillStyle = color; ctx.fillText(t, x, y);
    }
    if (showAsym){
      haloText('Slant asymptote', px(1.7), py(6.3), TEAL);
      haloText('y = 3x + 1', px(1.7), py(5.2), TEAL);
      haloText('x = 1', px(1.15), py(-7.6), ORANGE);
